package com.choicemanhelper;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(ChoiceManHelperConfig.GROUP)
public interface ChoiceManHelperConfig extends Config
{
	String GROUP = "choicemanhelper";

	@ConfigItem(
		keyName = "includeRecommended",
		name = "Include recommended items",
		description = "Count recommended (not strictly required) items toward a quest's readiness."
	)
	default boolean includeRecommended()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showMiniquests",
		name = "Show miniquests",
		description = "Include miniquests in the quest list."
	)
	default boolean showMiniquests()
	{
		return true;
	}
}

package com.choicemanhelper;

import com.choicemanhelper.model.MinigameEvaluation;
import com.choicemanhelper.model.QuestEvaluation;
import com.choicemanhelper.ui.ChoiceManHelperPanel;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.List;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Choice Man Helper",
	description = "Shows, per quest, whether your Choice Man unlocks make it completeable.",
	tags = {"choice", "man", "quest", "ironman", "unlock"}
)
public class ChoiceManHelperPlugin extends Plugin
{
	private static final int REFRESH_TICK_INTERVAL = 25;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ChoiceManHelperConfig config;

	@Inject
	private UnlockService unlockService;

	@Inject
	private QuestDataStore questDataStore;

	@Inject
	private MinigameDataStore minigameDataStore;

	@Inject
	private QuestStateTracker questStateTracker;

	@Inject
	private PlayerStatsTracker playerStatsTracker;

	@Inject
	private QuestEvaluator questEvaluator;

	@Inject
	private MinigameEvaluator minigameEvaluator;

	private ChoiceManHelperPanel panel;
	private NavigationButton navButton;
	private int ticksSinceRefresh;

	@Override
	protected void startUp() throws Exception
	{
		unlockService.loadItemTable();
		unlockService.refresh();
		questDataStore.load();
		minigameDataStore.load();

		panel = injector.getInstance(ChoiceManHelperPanel.class);
		questStateTracker.setUpdateListener(this::refreshPanel);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/com/choicemanhelper/icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Choice Man Helper")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		refreshPanel();
		playerStatsTracker.refresh();
		questStateTracker.refresh();
	}

	@Override
	protected void shutDown() throws Exception
	{
		questStateTracker.setUpdateListener(null);
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		if (gameStateChanged.getGameState() == GameState.LOGGED_IN)
		{
			ticksSinceRefresh = 0;
			playerStatsTracker.refresh();
			questStateTracker.refresh();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (++ticksSinceRefresh >= REFRESH_TICK_INTERVAL)
		{
			ticksSinceRefresh = 0;
			playerStatsTracker.refresh();
			questStateTracker.refresh();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (UnlockService.CHOICEMAN_GROUP.equals(event.getGroup())
			&& UnlockService.UNLOCKED_DATA_KEY.equals(event.getKey()))
		{
			unlockService.refresh();
			refreshPanel();
		}
		else if (ChoiceManHelperConfig.GROUP.equals(event.getGroup()))
		{
			refreshPanel();
		}
	}

	private void refreshPanel()
	{
		if (panel == null)
		{
			return;
		}
		List<QuestEvaluation> evaluations = questEvaluator.evaluateAll();
		List<MinigameEvaluation> minigameEvaluations = minigameEvaluator.evaluateAll();
		boolean hasData = unlockService.hasChoiceManData();
		ChoiceManHelperPanel target = panel;
		SwingUtilities.invokeLater(() ->
			target.setEvaluations(evaluations, minigameEvaluations, hasData));
	}

	@Provides
	ChoiceManHelperConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ChoiceManHelperConfig.class);
	}
}

package com.choicemanhelper;

import com.choicemanhelper.model.MinigameData;
import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads the bundled minigame requirement dataset ({@code minigame_items.json}). Unlike quests there
 * is no RuneLite enum to key against, so the dataset is simply an ordered list of
 * {@link MinigameData} rows.
 */
@Slf4j
@Singleton
public class MinigameDataStore
{
	private static final String MINIGAME_DATA_RESOURCE = "/com/choicemanhelper/minigame_items.json";

	@Inject
	private Gson gson;

	private volatile List<MinigameData> minigames = Collections.emptyList();

	/** Root object of minigame_items.json. */
	private static final class MinigameDataFile
	{
		List<MinigameData> minigames;
	}

	/**
	 * Loads the dataset. Safe to call from any thread; touches no client state.
	 */
	public void load()
	{
		try (InputStream in = getClass().getResourceAsStream(MINIGAME_DATA_RESOURCE))
		{
			if (in == null)
			{
				log.warn("Minigame data resource not found: {}", MINIGAME_DATA_RESOURCE);
				return;
			}

			MinigameDataFile file = gson.fromJson(
				new InputStreamReader(in, StandardCharsets.UTF_8), MinigameDataFile.class);

			List<MinigameData> list = new ArrayList<>();
			if (file != null && file.minigames != null)
			{
				for (MinigameData data : file.minigames)
				{
					if (data != null && data.getName() != null)
					{
						list.add(data);
					}
				}
			}
			minigames = Collections.unmodifiableList(list);
			log.debug("Loaded minigame data for {} minigames", minigames.size());
		}
		catch (IOException | JsonSyntaxException e)
		{
			log.warn("Failed to load minigame data", e);
		}
	}

	/**
	 * All bundled minigame rows, in file order.
	 */
	public List<MinigameData> getAll()
	{
		return minigames;
	}

	public int size()
	{
		return minigames.size();
	}
}

package com.choicemanhelper;

import com.choicemanhelper.model.MinigameData;
import com.choicemanhelper.model.MinigameEvaluation;
import com.choicemanhelper.model.PlayerStats;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Function;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;

/**
 * Computes {@link MinigameEvaluation}s from the unlock set, the bundled minigame dataset, the cached
 * quest states (for prerequisites) and the cached player stats.
 *
 * <p>The gating math is shared with quests via {@link RequirementEvaluator}; this class only adds
 * the minigame-specific plumbing (no in-game state, no mid-content items).
 */
@Singleton
public class MinigameEvaluator
{
	private final RequirementEvaluator requirementEvaluator;
	private final MinigameDataStore minigameDataStore;
	private final QuestStateTracker questStateTracker;
	private final PlayerStatsTracker playerStatsTracker;
	private final ChoiceManHelperConfig config;

	@Inject
	public MinigameEvaluator(
		UnlockService unlockService,
		MinigameDataStore minigameDataStore,
		QuestStateTracker questStateTracker,
		PlayerStatsTracker playerStatsTracker,
		ChoiceManHelperConfig config)
	{
		this.requirementEvaluator = new RequirementEvaluator(unlockService);
		this.minigameDataStore = minigameDataStore;
		this.questStateTracker = questStateTracker;
		this.playerStatsTracker = playerStatsTracker;
		this.config = config;
	}

	/**
	 * Evaluates every bundled minigame using the current unlock set, cached quest states and stats.
	 */
	public List<MinigameEvaluation> evaluateAll()
	{
		PlayerStats stats = playerStatsTracker.snapshot();
		List<MinigameEvaluation> result = new ArrayList<>();
		for (MinigameData data : minigameDataStore.getAll())
		{
			result.add(evaluate(data, config.includeRecommended(), stats, this::prereqState));
		}
		return result;
	}

	private QuestState prereqState(String enumName)
	{
		try
		{
			return questStateTracker.getState(Quest.valueOf(enumName));
		}
		catch (IllegalArgumentException | NullPointerException e)
		{
			return null;
		}
	}

	/**
	 * Pure evaluation over explicit inputs; used directly by tests with constructed data.
	 *
	 * @param stats             the account's base skill levels and quest points
	 * @param prereqStateLookup maps a prerequisite quest's enum name to its cached state (null if
	 *                          unknown)
	 */
	public MinigameEvaluation evaluate(
		MinigameData data,
		boolean includeRecommended,
		PlayerStats stats,
		Function<String, QuestState> prereqStateLookup)
	{
		if (stats == null)
		{
			stats = PlayerStats.EMPTY;
		}

		if (data == null)
		{
			return null;
		}

		RequirementEvaluator.Breakdown b = requirementEvaluator.evaluate(
			data.getRequired(),
			Collections.emptyList(),
			data.getRecommended(),
			data.getSkillRequirements(),
			data.getQuestPoints(),
			data.getQuestPrerequisites(),
			includeRecommended,
			stats,
			prereqStateLookup);

		return new MinigameEvaluation(data.getId(), data.getName(), data.getWikiPage(), b.readiness,
			b.required, b.recommended, b.skills, b.prerequisites, b.questPointsRequired,
			b.questPointsCurrent, b.gatingUnlocked, b.gatingTotal, b.aggregateSatisfied,
			b.aggregateTotal);
	}
}

package com.choicemanhelper;

import com.choicemanhelper.model.PlayerStats;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;

/**
 * Caches the account progression the evaluator needs: base level per {@code net.runelite.api.Skill}
 * and total quest points. Reads must happen on the client thread, so {@link #refresh()} marshals
 * through {@link ClientThread#invoke}; the cached {@link PlayerStats} snapshot is then safe to read
 * off-thread.
 */
@Singleton
public class PlayerStatsTracker
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	private volatile PlayerStats snapshot = PlayerStats.EMPTY;

	/**
	 * Schedules a refresh of the cached stats on the client thread. Cheap to call repeatedly.
	 */
	public void refresh()
	{
		clientThread.invoke(this::refreshOnClientThread);
	}

	private void refreshOnClientThread()
	{
		Map<String, Integer> levels = new HashMap<>();
		for (Skill skill : Skill.values())
		{
			try
			{
				levels.put(skill.name(), client.getRealSkillLevel(skill));
			}
			catch (RuntimeException e)
			{
				// A skill can throw if read at the wrong time; skip and retry on the next refresh.
			}
		}

		int questPoints = 0;
		try
		{
			questPoints = client.getVarpValue(VarPlayerID.QP);
		}
		catch (RuntimeException e)
		{
			// Ignore; leave quest points at 0 until the next refresh succeeds.
		}

		snapshot = new PlayerStats(levels, questPoints);
	}

	/**
	 * The latest cached snapshot, or {@link PlayerStats#EMPTY} before the first successful refresh.
	 */
	public PlayerStats snapshot()
	{
		return snapshot;
	}
}

package com.choicemanhelper;

import com.choicemanhelper.model.QuestItemData;
import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Quest;

/**
 * Loads the bundled per-quest item dataset ({@code quest_items.json}) and maps it by the
 * {@code net.runelite.api.Quest} enum-constant name. Quests absent from the file simply have no
 * data, which the evaluator reports as {@code Readiness.NO_DATA}.
 */
@Slf4j
@Singleton
public class QuestDataStore
{
	private static final String QUEST_DATA_RESOURCE = "/com/choicemanhelper/quest_items.json";

	@Inject
	private Gson gson;

	private volatile Map<String, QuestItemData> byRuneliteQuest = Collections.emptyMap();

	/** Root object of quest_items.json. */
	private static final class QuestDataFile
	{
		List<QuestItemData> quests;
	}

	/**
	 * Loads and indexes the dataset. Safe to call from any thread; touches no client state.
	 */
	public void load()
	{
		try (InputStream in = getClass().getResourceAsStream(QUEST_DATA_RESOURCE))
		{
			if (in == null)
			{
				log.warn("Quest data resource not found: {}", QUEST_DATA_RESOURCE);
				return;
			}

			QuestDataFile file = gson.fromJson(
				new InputStreamReader(in, StandardCharsets.UTF_8), QuestDataFile.class);

			Map<String, QuestItemData> map = new HashMap<>();
			if (file != null && file.quests != null)
			{
				for (QuestItemData data : file.quests)
				{
					if (data != null && data.getRuneliteQuest() != null)
					{
						map.put(data.getRuneliteQuest(), data);
					}
				}
			}
			byRuneliteQuest = Collections.unmodifiableMap(map);
			log.debug("Loaded quest item data for {} quests", byRuneliteQuest.size());
		}
		catch (IOException | JsonSyntaxException e)
		{
			log.warn("Failed to load quest item data", e);
		}
	}

	/**
	 * The item data for a quest, or null if the dataset has no row for it.
	 */
	public QuestItemData getData(Quest quest)
	{
		if (quest == null)
		{
			return null;
		}
		return byRuneliteQuest.get(quest.name());
	}

	public int size()
	{
		return byRuneliteQuest.size();
	}
}

package com.choicemanhelper;

import com.choicemanhelper.model.PlayerStats;
import com.choicemanhelper.model.QuestEvaluation;
import com.choicemanhelper.model.QuestItemData;
import com.choicemanhelper.model.Readiness;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;

/**
 * Computes {@link QuestEvaluation}s from the unlock set, the bundled dataset, the cached quest
 * states and the cached player stats, per the rules in docs/PLAN.md.
 *
 * <p>The gating math itself lives in {@link RequirementEvaluator}, shared with
 * {@link MinigameEvaluator}; this class layers the quest-specific concerns on top: pulling a quest's
 * bundled data, its in-game {@link QuestState}, and resolving prerequisite quest states.
 */
@Singleton
public class QuestEvaluator
{
	private final RequirementEvaluator requirementEvaluator;
	private final QuestDataStore questDataStore;
	private final QuestStateTracker questStateTracker;
	private final PlayerStatsTracker playerStatsTracker;
	private final ChoiceManHelperConfig config;

	@Inject
	public QuestEvaluator(
		UnlockService unlockService,
		QuestDataStore questDataStore,
		QuestStateTracker questStateTracker,
		PlayerStatsTracker playerStatsTracker,
		ChoiceManHelperConfig config)
	{
		this.requirementEvaluator = new RequirementEvaluator(unlockService);
		this.questDataStore = questDataStore;
		this.questStateTracker = questStateTracker;
		this.playerStatsTracker = playerStatsTracker;
		this.config = config;
	}

	/**
	 * Evaluates every quest using the current dataset, unlock set, cached states and cached stats.
	 */
	public List<QuestEvaluation> evaluateAll()
	{
		List<QuestEvaluation> result = new ArrayList<>();
		for (Quest quest : Quest.values())
		{
			result.add(evaluate(quest));
		}
		return result;
	}

	/**
	 * Evaluates a single quest, pulling its data, state, player stats and the recommended-items
	 * toggle from the injected services. Prerequisite states are resolved against the cached quest
	 * states.
	 */
	public QuestEvaluation evaluate(Quest quest)
	{
		QuestItemData data = questDataStore.getData(quest);
		QuestState state = questStateTracker.getState(quest);
		PlayerStats stats = playerStatsTracker.snapshot();
		return evaluate(quest, state, data, config.includeRecommended(), stats, this::prereqState);
	}

	private QuestState prereqState(String enumName)
	{
		try
		{
			return questStateTracker.getState(Quest.valueOf(enumName));
		}
		catch (IllegalArgumentException | NullPointerException e)
		{
			return null;
		}
	}

	/**
	 * Pure evaluation over explicit inputs; used directly by tests with constructed data.
	 *
	 * @param stats             the account's base skill levels and quest points
	 * @param prereqStateLookup maps a prerequisite quest's enum name to its cached state (null if
	 *                          unknown)
	 */
	public QuestEvaluation evaluate(
		Quest quest,
		QuestState state,
		QuestItemData data,
		boolean includeRecommended,
		PlayerStats stats,
		Function<String, QuestState> prereqStateLookup)
	{
		if (stats == null)
		{
			stats = PlayerStats.EMPTY;
		}

		if (data == null)
		{
			return new QuestEvaluation(quest, state, Readiness.NO_DATA,
				new ArrayList<>(), new ArrayList<>(), new ArrayList<>(),
				new ArrayList<>(), new ArrayList<>(), 0, stats.getQuestPoints(), 0, 0, 0, 0);
		}

		RequirementEvaluator.Breakdown b = requirementEvaluator.evaluate(
			data.getRequired(),
			data.getObtainedDuringQuest(),
			data.getRecommended(),
			data.getSkillRequirements(),
			data.getQuestPoints(),
			data.getQuestPrerequisites(),
			includeRecommended,
			stats,
			prereqStateLookup);

		return new QuestEvaluation(quest, state, b.readiness, b.required, b.obtainedDuringQuest,
			b.recommended, b.skills, b.prerequisites, b.questPointsRequired, b.questPointsCurrent,
			b.gatingUnlocked, b.gatingTotal, b.aggregateSatisfied, b.aggregateTotal);
	}
}

package com.choicemanhelper;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.client.callback.ClientThread;

/**
 * Caches {@code Quest.getState(client)} for every {@code net.runelite.api.Quest} constant.
 * Reads must happen on the client thread, so {@link #refresh()} marshals through
 * {@link ClientThread#invoke}. An optional listener fires after each refresh so callers can
 * recompute and repaint.
 */
@Singleton
public class QuestStateTracker
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	private final Map<Quest, QuestState> stateCache = new ConcurrentHashMap<>();

	private volatile Runnable updateListener;

	/**
	 * Sets a callback invoked (on the client thread) after each refresh completes.
	 */
	public void setUpdateListener(Runnable updateListener)
	{
		this.updateListener = updateListener;
	}

	/**
	 * Schedules a refresh of every quest state on the client thread. Cheap to call repeatedly.
	 */
	public void refresh()
	{
		clientThread.invoke(this::refreshOnClientThread);
	}

	private void refreshOnClientThread()
	{
		for (Quest quest : Quest.values())
		{
			try
			{
				QuestState state = quest.getState(client);
				if (state != null)
				{
					stateCache.put(quest, state);
				}
			}
			catch (RuntimeException e)
			{
				// A few quest scripts can throw when read at the wrong time; skip and retry later.
			}
		}

		Runnable listener = updateListener;
		if (listener != null)
		{
			listener.run();
		}
	}

	/**
	 * The cached state for a quest, or null if it has not been read yet.
	 */
	public QuestState getState(Quest quest)
	{
		return stateCache.get(quest);
	}
}

package com.choicemanhelper;

import com.choicemanhelper.model.PlayerStats;
import com.choicemanhelper.model.PrerequisiteStatus;
import com.choicemanhelper.model.QuestRequirement;
import com.choicemanhelper.model.Readiness;
import com.choicemanhelper.model.RequirementStatus;
import com.choicemanhelper.model.SkillRequirement;
import com.choicemanhelper.model.SkillRequirementStatus;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;

/**
 * The gating brain shared by {@link QuestEvaluator} and {@link MinigameEvaluator}.
 *
 * <p>It folds four requirement dimensions into one {@link Readiness} status: gating items (items
 * unlockable in Choice Man), skill levels, quest points and prerequisite quests. Each is counted as
 * a blocker; content is READY only when every blocker is satisfied, BLOCKED when none are, PARTIAL
 * in between, and {@link Readiness#NO_ITEMS_NEEDED} when it has no blockers at all.
 *
 * <p>Item satisfaction: an id-set is satisfied only when at least one of its gating ids is actually
 * unlocked, or when it lists no gating ids at all (an empty/vague category or purely untradeable
 * items, which never gate). A non-gating alternate id never satisfies a set that also lists a gating
 * id: otherwise a mid-quest product would auto-satisfy a requirement whose real, unlockable item is
 * still locked. A skill requirement is satisfied when the account's base level meets it; a
 * quest-point requirement when total quest points meet it; a prerequisite when that quest's cached
 * state is {@code FINISHED}.
 *
 * <p>Stateless apart from the {@link UnlockService} reference, so both evaluators construct their own
 * instance from the injected service.
 */
class RequirementEvaluator
{
	private final UnlockService unlockService;

	RequirementEvaluator(UnlockService unlockService)
	{
		this.unlockService = unlockService;
	}

	/**
	 * The per-dimension breakdown plus the folded {@link Readiness} and aggregate counts. Immutable;
	 * each evaluator copies the fields it needs into its own evaluation type.
	 */
	static final class Breakdown
	{
		final List<RequirementStatus> required;
		final List<RequirementStatus> obtainedDuringQuest;
		final List<RequirementStatus> recommended;
		final List<SkillRequirementStatus> skills;
		final List<PrerequisiteStatus> prerequisites;
		final int questPointsRequired;
		final int questPointsCurrent;
		final int gatingUnlocked;
		final int gatingTotal;
		final int aggregateSatisfied;
		final int aggregateTotal;
		final Readiness readiness;

		private Breakdown(
			List<RequirementStatus> required,
			List<RequirementStatus> obtainedDuringQuest,
			List<RequirementStatus> recommended,
			List<SkillRequirementStatus> skills,
			List<PrerequisiteStatus> prerequisites,
			int questPointsRequired,
			int questPointsCurrent,
			int gatingUnlocked,
			int gatingTotal,
			int aggregateSatisfied,
			int aggregateTotal,
			Readiness readiness)
		{
			this.required = required;
			this.obtainedDuringQuest = obtainedDuringQuest;
			this.recommended = recommended;
			this.skills = skills;
			this.prerequisites = prerequisites;
			this.questPointsRequired = questPointsRequired;
			this.questPointsCurrent = questPointsCurrent;
			this.gatingUnlocked = gatingUnlocked;
			this.gatingTotal = gatingTotal;
			this.aggregateSatisfied = aggregateSatisfied;
			this.aggregateTotal = aggregateTotal;
			this.readiness = readiness;
		}
	}

	/**
	 * Evaluates one content entry over explicit requirement lists.
	 *
	 * @param obtained          items obtained mid-content that still gate (quests only; pass empty
	 *                          for minigames)
	 * @param stats             the account's base skill levels and quest points (null treated as
	 *                          {@link PlayerStats#EMPTY})
	 * @param prereqStateLookup maps a prerequisite quest's enum name to its cached state (null if
	 *                          unknown)
	 */
	Breakdown evaluate(
		List<QuestRequirement> requiredItems,
		List<QuestRequirement> obtainedItems,
		List<QuestRequirement> recommendedItems,
		List<SkillRequirement> skillRequirements,
		int questPoints,
		List<String> questPrerequisites,
		boolean includeRecommended,
		PlayerStats stats,
		Function<String, QuestState> prereqStateLookup)
	{
		if (stats == null)
		{
			stats = PlayerStats.EMPTY;
		}

		List<RequirementStatus> required = evaluateList(requiredItems);
		List<RequirementStatus> obtained = evaluateList(obtainedItems);
		List<RequirementStatus> recommended = evaluateList(recommendedItems);
		List<SkillRequirementStatus> skills = evaluateSkills(skillRequirements, stats);
		List<PrerequisiteStatus> prerequisites = evaluatePrereqs(questPrerequisites, prereqStateLookup);

		int gatingTotal = 0;
		int gatingUnlocked = 0;
		int[] itemTally = tallyGating(required);
		gatingTotal += itemTally[0];
		gatingUnlocked += itemTally[1];
		itemTally = tallyGating(obtained);
		gatingTotal += itemTally[0];
		gatingUnlocked += itemTally[1];
		if (includeRecommended)
		{
			itemTally = tallyGating(recommended);
			gatingTotal += itemTally[0];
			gatingUnlocked += itemTally[1];
		}

		int skillsMet = 0;
		for (SkillRequirementStatus status : skills)
		{
			if (status.isMet())
			{
				skillsMet++;
			}
		}

		int prereqsFinished = 0;
		for (PrerequisiteStatus status : prerequisites)
		{
			if (status.isFinished())
			{
				prereqsFinished++;
			}
		}

		int qpRequired = questPoints;
		int qpCurrent = stats.getQuestPoints();
		boolean hasQpReq = qpRequired > 0;
		boolean qpMet = qpCurrent >= qpRequired;

		int aggregateTotal = gatingTotal + skills.size() + (hasQpReq ? 1 : 0) + prerequisites.size();
		int aggregateSatisfied = gatingUnlocked + skillsMet + (hasQpReq && qpMet ? 1 : 0) + prereqsFinished;

		Readiness readiness;
		if (aggregateTotal == 0)
		{
			readiness = Readiness.NO_ITEMS_NEEDED;
		}
		else if (aggregateSatisfied == aggregateTotal)
		{
			readiness = Readiness.READY;
		}
		else if (aggregateSatisfied == 0)
		{
			readiness = Readiness.BLOCKED;
		}
		else
		{
			readiness = Readiness.PARTIAL;
		}

		return new Breakdown(required, obtained, recommended, skills, prerequisites,
			qpRequired, qpCurrent, gatingUnlocked, gatingTotal,
			aggregateSatisfied, aggregateTotal, readiness);
	}

	/** Returns {gatingTotal, gatingUnlocked} contributed by a list of item requirement statuses. */
	private int[] tallyGating(List<RequirementStatus> statuses)
	{
		int total = 0;
		int satisfied = 0;
		for (RequirementStatus status : statuses)
		{
			if (status.isGating())
			{
				total++;
				if (status.isSatisfied())
				{
					satisfied++;
				}
			}
		}
		return new int[]{total, satisfied};
	}

	private List<SkillRequirementStatus> evaluateSkills(List<SkillRequirement> requirements, PlayerStats stats)
	{
		List<SkillRequirementStatus> result = new ArrayList<>();
		if (requirements == null)
		{
			return result;
		}
		for (SkillRequirement requirement : requirements)
		{
			if (requirement == null)
			{
				continue;
			}
			int current = stats.getRealLevel(requirement.getSkill());
			boolean met = current >= requirement.getLevel();
			result.add(new SkillRequirementStatus(requirement, current, met));
		}
		return result;
	}

	private List<PrerequisiteStatus> evaluatePrereqs(
		List<String> prerequisites, Function<String, QuestState> prereqStateLookup)
	{
		List<PrerequisiteStatus> result = new ArrayList<>();
		if (prerequisites == null)
		{
			return result;
		}
		for (String enumName : prerequisites)
		{
			if (enumName == null || enumName.isEmpty())
			{
				continue;
			}
			QuestState state = prereqStateLookup == null ? null : prereqStateLookup.apply(enumName);
			boolean finished = state == QuestState.FINISHED;
			result.add(new PrerequisiteStatus(enumName, displayName(enumName), finished));
		}
		return result;
	}

	private static String displayName(String enumName)
	{
		try
		{
			return Quest.valueOf(enumName).getName();
		}
		catch (IllegalArgumentException e)
		{
			return enumName;
		}
	}

	private List<RequirementStatus> evaluateList(List<QuestRequirement> requirements)
	{
		List<RequirementStatus> result = new ArrayList<>();
		if (requirements == null)
		{
			return result;
		}
		for (QuestRequirement requirement : requirements)
		{
			boolean gating = hasGatingItem(requirement);
			boolean satisfied = isSatisfied(requirement);
			result.add(new RequirementStatus(requirement, satisfied, gating));
		}
		return result;
	}

	private boolean isSatisfied(QuestRequirement requirement)
	{
		List<QuestRequirement> groups = requirement.getAlternativeGroups();
		if (!groups.isEmpty())
		{
			for (QuestRequirement group : groups)
			{
				if (isIdSetSatisfied(group.getItemIds()))
				{
					return true;
				}
			}
			return false;
		}

		return isIdSetSatisfied(requirement.getItemIds());
	}

	/**
	 * An id-set is satisfied when at least one of its gating ids is unlocked, or when it has no
	 * gating ids at all (an empty/vague category or purely untradeable items, which never gate).
	 */
	private boolean isIdSetSatisfied(List<Integer> itemIds)
	{
		boolean hasGating = false;
		for (Integer id : itemIds)
		{
			if (id == null)
			{
				continue;
			}
			if (unlockService.isGating(id))
			{
				hasGating = true;
				if (unlockService.isUnlocked(id))
				{
					return true;
				}
			}
		}
		return !hasGating;
	}

	private boolean hasGatingItem(QuestRequirement requirement)
	{
		for (Integer id : requirement.getItemIds())
		{
			if (id != null && unlockService.isGating(id))
			{
				return true;
			}
		}
		for (QuestRequirement group : requirement.getAlternativeGroups())
		{
			for (Integer id : group.getItemIds())
			{
				if (id != null && unlockService.isGating(id))
				{
					return true;
				}
			}
		}
		return false;
	}
}

package com.choicemanhelper;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Reads Choice Man's unlock state and answers gating questions about individual item IDs.
 *
 * <p>The bundled {@code choiceman_items.json} (a copy of Choice Man's own item table) is inverted
 * into an itemId -&gt; base name map. An item ID gates a quest if and only if it is present in that
 * table; anything absent cannot be unlocked in the mode and is therefore freely usable. The live
 * unlock set is read from RuneLite's {@link ConfigManager} under group {@code choiceman}, key
 * {@code unlockedItems.data} (a JSON array of base names), the same value Choice Man syncs on every
 * unlock.
 */
@Slf4j
@Singleton
public class UnlockService
{
	static final String CHOICEMAN_GROUP = "choiceman";
	static final String UNLOCKED_DATA_KEY = "unlockedItems.data";
	private static final String ITEM_TABLE_RESOURCE = "/com/choicemanhelper/choiceman_items.json";

	@Inject
	private Gson gson;

	@Inject
	private ConfigManager configManager;

	private volatile Map<Integer, String> idToBase = Collections.emptyMap();
	private volatile Set<String> unlockedBases = Collections.emptySet();
	private volatile boolean choiceManDataPresent = false;

	/** Bundled item-table row: base name to concrete item IDs. */
	private static final class ItemEntry
	{
		String name;
		List<Integer> ids;
	}

	/**
	 * Loads and inverts the bundled item table. Safe to call from any thread; touches no client
	 * state. Call once at start up.
	 */
	public void loadItemTable()
	{
		try (InputStream in = getClass().getResourceAsStream(ITEM_TABLE_RESOURCE))
		{
			if (in == null)
			{
				log.warn("Choice Man item table resource not found: {}", ITEM_TABLE_RESOURCE);
				return;
			}

			Type listType = new TypeToken<List<ItemEntry>>()
			{
			}.getType();
			List<ItemEntry> entries = gson.fromJson(
				new InputStreamReader(in, StandardCharsets.UTF_8), listType);

			Map<Integer, String> map = new HashMap<>();
			if (entries != null)
			{
				for (ItemEntry entry : entries)
				{
					if (entry == null || entry.name == null || entry.ids == null)
					{
						continue;
					}
					for (Integer id : entry.ids)
					{
						if (id != null)
						{
							map.put(id, entry.name);
						}
					}
				}
			}
			idToBase = Collections.unmodifiableMap(map);
			log.debug("Loaded Choice Man item table: {} id mappings", idToBase.size());
		}
		catch (IOException | JsonSyntaxException e)
		{
			log.warn("Failed to load Choice Man item table", e);
		}
	}

	/**
	 * Re-reads the live unlocked base-name set from the Choice Man config group. Treats a missing
	 * value as an empty set and records that Choice Man data was not found. Call on start up and
	 * whenever a {@code ConfigChanged} for the relevant key arrives.
	 */
	public void refresh()
	{
		String json = configManager.getConfiguration(CHOICEMAN_GROUP, UNLOCKED_DATA_KEY);
		if (json == null || json.isEmpty())
		{
			choiceManDataPresent = false;
			unlockedBases = Collections.emptySet();
			return;
		}

		try
		{
			Type setType = new TypeToken<Set<String>>()
			{
			}.getType();
			Set<String> parsed = gson.fromJson(json, setType);
			unlockedBases = parsed == null ? Collections.emptySet() : new HashSet<>(parsed);
			choiceManDataPresent = true;
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Failed to parse Choice Man unlocked items data", e);
			choiceManDataPresent = false;
			unlockedBases = Collections.emptySet();
		}
	}

	/**
	 * True if the item ID is either non-gating (not in the Choice Man table, so always usable) or
	 * its base name has been unlocked.
	 */
	public boolean isUnlocked(int itemId)
	{
		String base = idToBase.get(itemId);
		if (base == null)
		{
			return true;
		}
		return unlockedBases.contains(base);
	}

	/**
	 * True if this item ID is tracked by Choice Man and therefore can gate a quest.
	 */
	public boolean isGating(int itemId)
	{
		return idToBase.containsKey(itemId);
	}

	/**
	 * The Choice Man base name for an item ID, or null if the item is untracked.
	 */
	public String baseNameFor(int itemId)
	{
		return idToBase.get(itemId);
	}

	/**
	 * Whether a non-empty Choice Man unlock set was found in config. When false, the UI should warn
	 * that Choice Man data was not found.
	 */
	public boolean hasChoiceManData()
	{
		return choiceManDataPresent;
	}

	/**
	 * Test-only factory that installs a fixed item table and unlock set without touching config or
	 * bundled resources.
	 */
	static UnlockService createForTest(Map<Integer, String> idToBase, Set<String> unlockedBases)
	{
		UnlockService service = new UnlockService();
		service.idToBase = Collections.unmodifiableMap(new HashMap<>(idToBase));
		service.unlockedBases = new HashSet<>(unlockedBases);
		service.choiceManDataPresent = true;
		return service;
	}
}

package com.choicemanhelper.model;

import java.util.Collections;
