	{
		return required == null ? Collections.emptyList() : required;
	}

	public List<QuestRequirement> getRecommended()
	{
		return recommended == null ? Collections.emptyList() : recommended;
	}

	/**
	 * Skill-level requirements to take part. Empty when no data has been recorded.
	 */
	public List<SkillRequirement> getSkillRequirements()
	{
		return skillRequirements == null ? Collections.emptyList() : skillRequirements;
	}

	/**
	 * Minimum total quest points the minigame needs, or 0 when it has no quest-point requirement.
	 */
