package com.choicemanhelper.model;

import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * An immutable snapshot of the account progression the evaluator needs: the base (unboosted) level
 * per skill, keyed by {@code net.runelite.api.Skill} enum-constant name, and the current total
 * quest points. Built on the client thread by {@code PlayerStatsTracker} and read off-thread by the
 * evaluator, so it never touches live client state itself.
 */
public class PlayerStats
{
	/** A snapshot with no levels and zero quest points, used before login. */
	public static final PlayerStats EMPTY = new PlayerStats(Collections.emptyMap(), 0);

	private final Map<String, Integer> realLevels;
	private final int questPoints;

	public PlayerStats(Map<String, Integer> realLevels, int questPoints)
	{
		Map<String, Integer> copy = new HashMap<>();
		if (realLevels != null)
		{
			for (Map.Entry<String, Integer> e : realLevels.entrySet())
			{
				if (e.getKey() != null && e.getValue() != null)
				{
					copy.put(e.getKey().toUpperCase(Locale.ROOT), e.getValue());
				}
			}
		}
		this.realLevels = Collections.unmodifiableMap(copy);
		this.questPoints = questPoints;
	}

	/**
	 * The account's base level in the named skill (a {@code Skill} enum-constant name), or 0 if the
	 * skill is unknown or has not been read yet.
	 */
	public int getRealLevel(String skillName)
	{
		if (skillName == null)
		{
			return 0;
		}
		Integer level = realLevels.get(skillName.toUpperCase(Locale.ROOT));
		return level == null ? 0 : level;
	}

	public int getQuestPoints()
	{
		return questPoints;
	}
}

