package com.choicemanhelper.model;

import java.util.Collections;
import java.util.List;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;

/**
 * The full evaluation of one quest: its in-game progress state, its Choice Man readiness, and the
 * per-requirement breakdown split by category.
 *
 * <p>Readiness folds four dimensions into one status: gating items (unlocked in Choice Man), skill
 * levels, quest points, and prerequisite quests. {@code aggregateSatisfied}/{@code aggregateTotal}
 * count all four; the item-only {@code gatingUnlocked}/{@code gatingTotal} pair is kept for the
 * detail view.
 */
public class QuestEvaluation
{
	private final Quest quest;
	private final QuestState questState;
	private final Readiness readiness;
	private final List<RequirementStatus> required;
	private final List<RequirementStatus> obtainedDuringQuest;
	private final List<RequirementStatus> recommended;
	private final List<SkillRequirementStatus> skillRequirements;
	private final List<PrerequisiteStatus> prerequisites;
	private final int questPointsRequired;
	private final int questPointsCurrent;
	private final int gatingUnlocked;
	private final int gatingTotal;
	private final int aggregateSatisfied;
	private final int aggregateTotal;

	public QuestEvaluation(
		Quest quest,
		QuestState questState,
		Readiness readiness,
		List<RequirementStatus> required,
		List<RequirementStatus> obtainedDuringQuest,
		List<RequirementStatus> recommended,
		List<SkillRequirementStatus> skillRequirements,
		List<PrerequisiteStatus> prerequisites,
		int questPointsRequired,
		int questPointsCurrent,
		int gatingUnlocked,
		int gatingTotal,
		int aggregateSatisfied,
		int aggregateTotal)
	{
		this.quest = quest;
		this.questState = questState;
		this.readiness = readiness;
		this.required = required == null ? Collections.emptyList() : required;
		this.obtainedDuringQuest = obtainedDuringQuest == null ? Collections.emptyList() : obtainedDuringQuest;
		this.recommended = recommended == null ? Collections.emptyList() : recommended;
		this.skillRequirements = skillRequirements == null ? Collections.emptyList() : skillRequirements;
		this.prerequisites = prerequisites == null ? Collections.emptyList() : prerequisites;
		this.questPointsRequired = questPointsRequired;
		this.questPointsCurrent = questPointsCurrent;
		this.gatingUnlocked = gatingUnlocked;
		this.gatingTotal = gatingTotal;
		this.aggregateSatisfied = aggregateSatisfied;
		this.aggregateTotal = aggregateTotal;
	}

	public Quest getQuest()
	{
		return quest;
	}

	/**
	 * The cached in-game state, or null if it has not been read yet (for example before login).
	 */
	public QuestState getQuestState()
	{
		return questState;
	}

	public Readiness getReadiness()
	{
		return readiness;
	}

	public List<RequirementStatus> getRequired()
	{
		return required;
	}

	public List<RequirementStatus> getObtainedDuringQuest()
	{
		return obtainedDuringQuest;
	}

	public List<RequirementStatus> getRecommended()
	{
		return recommended;
	}

	public List<SkillRequirementStatus> getSkillRequirements()
	{
		return skillRequirements;
	}

	public List<PrerequisiteStatus> getPrerequisites()
