	/**
	 * The quest-point requirement, or 0 when the quest has none.
	 */
	public int getQuestPointsRequired()
	{
		return questPointsRequired;
	}

	/**
	 * The account's current total quest points at evaluation time.
	 */
	public int getQuestPointsCurrent()
	{
		return questPointsCurrent;
	}

	public int getGatingUnlocked()
	{
		return gatingUnlocked;
	}

	public int getGatingTotal()
	{
		return gatingTotal;
	}

	/**
	 * Number of satisfied blockers across all four dimensions (items, skills, quest points,
	 * prerequisites).
