/**
 * One logical item requirement for a quest.
 *
 * <p>{@code itemIds} is the ordered set of interchangeable item IDs that satisfy this single
 * requirement (first entry is canonical). An empty list means a vague category entry (for
 * example "weight-reducing clothing") that is shown informationally but never gates a quest.
 * {@code alternativeGroups}, when present, models a genuine either/or between DIFFERENT logical
 * purchases (for example runes versus a coin payment); the requirement is satisfied when any one
 * group is satisfied.
 */
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class QuestRequirement
{
	private String name;
	private List<Integer> itemIds;
	private int quantity;
	private List<QuestRequirement> alternativeGroups;
	private Boolean tradeableGE;
	private String source;
	private String notes;

	public String getName()
	{
		return name;
	}

	public List<Integer> getItemIds()
	{
		return itemIds == null ? Collections.emptyList() : itemIds;
	}

	/**
	 * Quantity needed. A missing or zero quantity is treated as 1.
	 */
	public int getQuantity()
	{
		return quantity <= 0 ? 1 : quantity;
	}

	public List<QuestRequirement> getAlternativeGroups()
	{
		return alternativeGroups == null ? Collections.emptyList() : alternativeGroups;
	}

	public Boolean getTradeableGE()
	{
		return tradeableGE;
	}

	public String getSource()
	{
		return source;
	}

	public String getNotes()
	{
		return notes;
	}
}

