	/** At least one gating item is needed and none are unlocked. */
	BLOCKED("Blocked"),
	/** The quest has no blockers at all (no gating items, skill, quest-point or prerequisite reqs). */
	NO_ITEMS_NEEDED("Nothing needed"),
	/** No bundled item data exists for this quest yet. */
	NO_DATA("No data");

	private final String label;

	Readiness(String label)
	{
		this.label = label;
	}

	public String getLabel()
	{
		return label;
	}
}

