package com.choicemanhelper.ui;

import com.choicemanhelper.model.MinigameEvaluation;
import com.choicemanhelper.model.QuestEvaluation;
import com.choicemanhelper.model.Readiness;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import javax.swing.Timer;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.api.QuestState;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * The side panel: a Quests / Minigames tab toggle, a search box, progress and readiness filters, and
 * the scrollable list of {@link QuestRow}s or {@link MinigameRow}s. Readiness is computed by the
 * plugin and pushed in via {@link #setEvaluations}; filtering and search happen locally and are
 * debounced.
 */
public class ChoiceManHelperPanel extends PluginPanel
{
	private static final int DEBOUNCE_MS = 250;

	private enum Tab
	{
		QUESTS,
		MINIGAMES
	}

	private enum ProgressFilter
	{
		ALL("All"),
		NOT_STARTED("Not started"),
		IN_PROGRESS("In progress"),
		FINISHED("Finished");

		private final String label;

		ProgressFilter(String label)
		{
			this.label = label;
		}

		boolean matches(QuestState state)
		{
			switch (this)
			{
				case ALL:
					return true;
				case NOT_STARTED:
					return state == QuestState.NOT_STARTED;
				case IN_PROGRESS:
					return state == QuestState.IN_PROGRESS;
				case FINISHED:
					return state == QuestState.FINISHED;
				default:
					return true;
			}
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	private enum ReadinessFilter
	{
		ALL("All", null),
		READY("Ready", Readiness.READY),
		PARTIAL("Partial", Readiness.PARTIAL),
		BLOCKED("Blocked", Readiness.BLOCKED),
		NO_DATA("No data", Readiness.NO_DATA);

		private final String label;
		private final Readiness readiness;

		ReadinessFilter(String label, Readiness readiness)
		{
			this.label = label;
			this.readiness = readiness;
		}

		boolean matches(Readiness value)
		{
			return readiness == null || readiness == value;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	private final JLabel warningLabel = new JLabel();
	private final JLabel questsTab = new JLabel("Quests", SwingConstants.CENTER);
	private final JLabel minigamesTab = new JLabel("Minigames", SwingConstants.CENTER);
	private final JTextField searchField = new JTextField();
	private final JLabel progressLabel = filterLabel("Progress");
	private final JComboBox<ProgressFilter> progressFilter = new JComboBox<>(ProgressFilter.values());
	private final JComboBox<ReadinessFilter> readinessFilter = new JComboBox<>(ReadinessFilter.values());
	private final JPanel listPanel = new JPanel();
	private final Timer debounce;

	private List<QuestEvaluation> evaluations = new ArrayList<>();
	private List<MinigameEvaluation> minigameEvaluations = new ArrayList<>();
	private Tab activeTab = Tab.QUESTS;

	/** Enum names of quests the user has expanded; kept across refreshes so rows do not auto-close. */
	private final Set<String> expandedQuests = new HashSet<>();
	/** Ids of minigames the user has expanded; kept across refreshes so rows do not auto-close. */
	private final Set<String> expandedMinigames = new HashSet<>();

	public ChoiceManHelperPanel()
	{
		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		debounce = new Timer(DEBOUNCE_MS, e -> applyFilters());
		debounce.setRepeats(false);

		add(buildControls(), BorderLayout.NORTH);

		listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
		listPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		JPanel listWrap = new JPanel(new BorderLayout());
		listWrap.setBackground(ColorScheme.DARK_GRAY_COLOR);
		listWrap.add(listPanel, BorderLayout.NORTH);
		add(listWrap, BorderLayout.CENTER);
	}

	private JPanel buildControls()
	{
		JPanel controls = new JPanel();
		controls.setLayout(new BoxLayout(controls, BoxLayout.Y_AXIS));
		controls.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));

		JLabel title = new JLabel("Choice Man Helper");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(ColorScheme.BRAND_ORANGE);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		controls.add(title);

		warningLabel.setFont(FontManager.getRunescapeSmallFont());
		warningLabel.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		warningLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		warningLabel.setVisible(false);
		controls.add(warningLabel);

		JLabel note = new JLabel("<html>Unlocks are stored per RuneLite install, not per account.</html>");
		note.setFont(FontManager.getRunescapeSmallFont());
		note.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		note.setAlignmentX(Component.LEFT_ALIGNMENT);
		note.setBorder(BorderFactory.createEmptyBorder(2, 0, 6, 0));
		controls.add(note);

		controls.add(buildTabs());

		searchField.setToolTipText("Search");
		searchField.putClientProperty("JTextField.placeholderText", "Search");
		searchField.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		searchField.setAlignmentX(Component.LEFT_ALIGNMENT);
		searchField.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				debounce.restart();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				debounce.restart();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				debounce.restart();
			}
		});
		controls.add(searchField);

		progressFilter.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		progressFilter.setAlignmentX(Component.LEFT_ALIGNMENT);
		progressFilter.addActionListener(e -> debounce.restart());
		readinessFilter.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		readinessFilter.setAlignmentX(Component.LEFT_ALIGNMENT);
		readinessFilter.addActionListener(e -> debounce.restart());

		JPanel filters = new JPanel(new GridLayout(2, 2, 4, 2));
		filters.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
		filters.setAlignmentX(Component.LEFT_ALIGNMENT);
		filters.setMaximumSize(new Dimension(Integer.MAX_VALUE, 56));
		filters.add(progressLabel);
		filters.add(filterLabel("Readiness"));
		filters.add(progressFilter);
		filters.add(readinessFilter);
		controls.add(filters);

		return controls;
	}

	private JPanel buildTabs()
	{
		JPanel tabs = new JPanel(new GridLayout(1, 2, 4, 0));
		tabs.setAlignmentX(Component.LEFT_ALIGNMENT);
		tabs.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		tabs.setBorder(BorderFactory.createEmptyBorder(2, 0, 4, 0));
		tabs.setBackground(ColorScheme.DARK_GRAY_COLOR);

		styleTab(questsTab, Tab.QUESTS);
		styleTab(minigamesTab, Tab.MINIGAMES);
		tabs.add(questsTab);
		tabs.add(minigamesTab);
		paintTabs();
		return tabs;
	}

	private void styleTab(JLabel tab, Tab which)
	{
		tab.setFont(FontManager.getRunescapeSmallFont());
		tab.setOpaque(true);
		tab.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));
		tab.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
		tab.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (activeTab != which)
				{
					activeTab = which;
					paintTabs();
					applyFilters();
				}
			}
		});
	}

	private void paintTabs()
	{
		boolean quests = activeTab == Tab.QUESTS;
		questsTab.setBackground(quests ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR);
		questsTab.setForeground(quests ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.LIGHT_GRAY_COLOR);
		minigamesTab.setBackground(!quests ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR);
		minigamesTab.setForeground(!quests ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.LIGHT_GRAY_COLOR);
		// Progress filtering only applies to quests; grey it out on the minigames tab.
		progressLabel.setEnabled(quests);
		progressFilter.setEnabled(quests);
	}

	private static JLabel filterLabel(String text)
	{
		JLabel label = new JLabel(text, SwingConstants.LEFT);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return label;
	}

	/**
	 * Replaces the evaluated quest and minigame lists and repaints. Must be called on the EDT.
	 */
	public void setEvaluations(
		List<QuestEvaluation> evaluations,
		List<MinigameEvaluation> minigameEvaluations,
		boolean hasChoiceManData)
	{
		this.evaluations = evaluations == null ? new ArrayList<>() : evaluations;
		this.minigameEvaluations = minigameEvaluations == null ? new ArrayList<>() : minigameEvaluations;
		warningLabel.setText("<html>Choice Man data not found. No unlocks have been recorded on this RuneLite install yet.</html>");
		warningLabel.setVisible(!hasChoiceManData);
		applyFilters();
	}

	private void applyFilters()
	{
		if (activeTab == Tab.MINIGAMES)
		{
			applyMinigameFilters();
			return;
		}
		applyQuestFilters();
	}

	private void applyQuestFilters()
	{
		String query = searchText();
		ProgressFilter progress = (ProgressFilter) progressFilter.getSelectedItem();
		ReadinessFilter readiness = (ReadinessFilter) readinessFilter.getSelectedItem();

		listPanel.removeAll();
		int shown = 0;
		for (QuestEvaluation evaluation : evaluations)
		{
			if (progress != null && !progress.matches(evaluation.getQuestState()))
			{
				continue;
			}
			if (readiness != null && !readiness.matches(evaluation.getReadiness()))
			{
				continue;
			}
			if (!query.isEmpty()
				&& !evaluation.getQuest().getName().toLowerCase(Locale.ROOT).contains(query))
			{
				continue;
			}
			String key = evaluation.getQuest().name();
			listPanel.add(new QuestRow(evaluation, expandedQuests.contains(key), expanded ->
			{
				if (expanded)
				{
					expandedQuests.add(key);
				}
				else
				{
					expandedQuests.remove(key);
				}
			}));
			shown++;
		}

		finishList(shown, "No quests match the current filters.");
	}

	private void applyMinigameFilters()
	{
		String query = searchText();
		ReadinessFilter readiness = (ReadinessFilter) readinessFilter.getSelectedItem();

		listPanel.removeAll();
		int shown = 0;
		for (MinigameEvaluation evaluation : minigameEvaluations)
		{
			if (readiness != null && !readiness.matches(evaluation.getReadiness()))
			{
				continue;
			}
			if (!query.isEmpty()
				&& !evaluation.getName().toLowerCase(Locale.ROOT).contains(query))
			{
				continue;
			}
			String key = evaluation.getId();
			listPanel.add(new MinigameRow(evaluation, expandedMinigames.contains(key), expanded ->
			{
				if (expanded)
				{
					expandedMinigames.add(key);
				}
				else
				{
					expandedMinigames.remove(key);
				}
			}));
			shown++;
		}

		String empty = minigameEvaluations.isEmpty()
			? "No minigame data bundled yet." : "No minigames match the current filters.";
		finishList(shown, empty);
	}

	private String searchText()
	{
		return searchField.getText() == null
			? "" : searchField.getText().trim().toLowerCase(Locale.ROOT);
	}

	private void finishList(int shown, String emptyMessage)
	{
		if (shown == 0)
		{
			JLabel empty = new JLabel(emptyMessage);
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			empty.setBorder(BorderFactory.createEmptyBorder(8, 4, 0, 0));
			listPanel.add(empty);
		}

		listPanel.revalidate();
		listPanel.repaint();
	}
}

package com.choicemanhelper.ui;

import com.choicemanhelper.model.MinigameEvaluation;
import com.choicemanhelper.model.PrerequisiteStatus;
import com.choicemanhelper.model.QuestRequirement;
import com.choicemanhelper.model.RequirementStatus;
import com.choicemanhelper.model.SkillRequirement;
import com.choicemanhelper.model.SkillRequirementStatus;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.Locale;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.api.Skill;
import net.runelite.client.ui.ColorScheme;
