/**
 * A single expandable minigame entry: a clickable header (readiness indicator, minigame name,
 * blocker count) revealing the per-requirement breakdown when clicked. Mirrors {@link QuestRow}
 * without any in-game progress state.
 */
class MinigameRow extends JPanel
{
	private static final Color INFO_COLOR = ColorScheme.LIGHT_GRAY_COLOR;
	private static final Color GOOD_COLOR = ColorScheme.PROGRESS_COMPLETE_COLOR;
	private static final Color BAD_COLOR = ColorScheme.PROGRESS_ERROR_COLOR;

	private final JPanel detail;
	private boolean expanded;

	/**
	 * @param expanded whether this row starts expanded (the panel keeps this state across refreshes)
	 * @param onToggle notified with the new expanded state whenever the user toggles the row
	 */
	MinigameRow(MinigameEvaluation evaluation, boolean expanded, Consumer<Boolean> onToggle)
	{
		this.expanded = expanded;
		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(3, 0, 3, 0));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JPanel header = buildHeader(evaluation);
		detail = buildDetail(evaluation);
		detail.setVisible(expanded);

		add(header, BorderLayout.NORTH);
		add(detail, BorderLayout.CENTER);

		MouseAdapter toggle = new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				MinigameRow.this.expanded = !MinigameRow.this.expanded;
				detail.setVisible(MinigameRow.this.expanded);
				onToggle.accept(MinigameRow.this.expanded);
				revalidate();
				repaint();
			}
		};
		header.addMouseListener(toggle);
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
	}

	private JPanel buildHeader(MinigameEvaluation evaluation)
	{
		JPanel header = new JPanel(new BorderLayout(6, 0));
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setBorder(BorderFactory.createEmptyBorder(3, 6, 3, 6));

		JPanel indicator = new JPanel();
		indicator.setPreferredSize(new Dimension(10, 10));
		indicator.setBackground(QuestRow.readinessColor(evaluation.getReadiness()));
		indicator.setToolTipText(evaluation.getReadiness().getLabel());
		JPanel indicatorWrap = new JPanel(new BorderLayout());
		indicatorWrap.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		indicatorWrap.setBorder(BorderFactory.createEmptyBorder(3, 0, 0, 0));
		indicatorWrap.add(indicator, BorderLayout.NORTH);
		header.add(indicatorWrap, BorderLayout.WEST);

		JLabel name = new JLabel(evaluation.getName());
		name.setFont(FontManager.getRunescapeSmallFont());
