/**
 * A single expandable quest entry: a clickable header (readiness indicator, quest name, gating
 * item count) that reveals the per-requirement breakdown when clicked.
 */
class QuestRow extends JPanel
{
	private static final Color INFO_COLOR = ColorScheme.LIGHT_GRAY_COLOR;
	private static final Color GOOD_COLOR = ColorScheme.PROGRESS_COMPLETE_COLOR;
	private static final Color BAD_COLOR = ColorScheme.PROGRESS_ERROR_COLOR;

	private final JPanel detail;
	private boolean expanded;

	/**
	 * @param expanded whether this row starts expanded (the panel keeps this state across refreshes)
	 * @param onToggle notified with the new expanded state whenever the user toggles the row
	 */
	QuestRow(QuestEvaluation evaluation, boolean expanded, Consumer<Boolean> onToggle)
	{
		this.expanded = expanded;
		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(3, 0, 3, 0));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JPanel header = buildHeader(evaluation);
		detail = buildDetail(evaluation);
		detail.setVisible(expanded);

		add(header, BorderLayout.NORTH);
		add(detail, BorderLayout.CENTER);

		MouseAdapter toggle = new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				QuestRow.this.expanded = !QuestRow.this.expanded;
				detail.setVisible(QuestRow.this.expanded);
				onToggle.accept(QuestRow.this.expanded);
				revalidate();
				repaint();
			}
		};
		header.addMouseListener(toggle);
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
	}

	private JPanel buildHeader(QuestEvaluation evaluation)
	{
		JPanel header = new JPanel(new BorderLayout(6, 0));
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setBorder(BorderFactory.createEmptyBorder(3, 6, 3, 6));

		JPanel indicator = new JPanel();
		indicator.setPreferredSize(new Dimension(10, 10));
		indicator.setBackground(readinessColor(evaluation.getReadiness()));
		indicator.setToolTipText(evaluation.getReadiness().getLabel());
		JPanel indicatorWrap = new JPanel(new BorderLayout());
		indicatorWrap.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		indicatorWrap.setBorder(BorderFactory.createEmptyBorder(3, 0, 0, 0));
		indicatorWrap.add(indicator, BorderLayout.NORTH);
		header.add(indicatorWrap, BorderLayout.WEST);

		JLabel name = new JLabel(nameText(evaluation));
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(isFinished(evaluation) ? ColorScheme.LIGHT_GRAY_COLOR : Color.WHITE);
		header.add(name, BorderLayout.CENTER);

		JLabel count = new JLabel(countText(evaluation));
		count.setFont(FontManager.getRunescapeSmallFont());
		count.setForeground(readinessColor(evaluation.getReadiness()));
		header.add(count, BorderLayout.EAST);

		return header;
	}

	private JPanel buildDetail(QuestEvaluation evaluation)
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(4, 10, 4, 6));

		addSection(panel, "Required", evaluation.getRequired());
		addSection(panel, "During quest", evaluation.getObtainedDuringQuest());
		addSection(panel, "Recommended", evaluation.getRecommended());
		addSkillSection(panel, evaluation.getSkillRequirements());
		addQuestPointsSection(panel, evaluation);
		addPrerequisiteSection(panel, evaluation.getPrerequisites());

		if (panel.getComponentCount() == 0)
		{
			panel.add(mutedLabel("No item data recorded."));
		}
		return panel;
	}

	private void addSkillSection(JPanel panel, List<SkillRequirementStatus> statuses)
	{
		if (statuses.isEmpty())
		{
			return;
		}

		panel.add(sectionHeading("Skills"));
		for (SkillRequirementStatus status : statuses)
		{
			SkillRequirement req = status.getRequirement();
			String text = req.getLevel() + " " + skillDisplayName(req.getSkill())
				+ " (have " + status.getCurrentLevel() + ")";
			panel.add(coloredLine(text, status.isMet() ? GOOD_COLOR : BAD_COLOR));
		}
	}

	private void addQuestPointsSection(JPanel panel, QuestEvaluation evaluation)
	{
		if (evaluation.getQuestPointsRequired() <= 0)
		{
			return;
		}

		panel.add(sectionHeading("Quest points"));
		boolean met = evaluation.getQuestPointsCurrent() >= evaluation.getQuestPointsRequired();
		String text = evaluation.getQuestPointsRequired() + " quest points (have "
			+ evaluation.getQuestPointsCurrent() + ")";
		panel.add(coloredLine(text, met ? GOOD_COLOR : BAD_COLOR));
	}

	private void addPrerequisiteSection(JPanel panel, List<PrerequisiteStatus> statuses)
	{
		if (statuses.isEmpty())
		{
			return;
		}

		panel.add(sectionHeading("Prerequisites"));
		for (PrerequisiteStatus status : statuses)
		{
			panel.add(coloredLine(status.getDisplayName(), status.isFinished() ? GOOD_COLOR : BAD_COLOR));
		}
	}

	private static JLabel sectionHeading(String title)
	{
		JLabel heading = new JLabel(title);
		heading.setFont(FontManager.getRunescapeSmallFont());
		heading.setForeground(ColorScheme.BRAND_ORANGE);
		heading.setAlignmentX(Component.LEFT_ALIGNMENT);
		heading.setBorder(BorderFactory.createEmptyBorder(3, 0, 1, 0));
		return heading;
	}

	private static JLabel coloredLine(String text, Color color)
	{
		JLabel line = new JLabel(text);
		line.setFont(FontManager.getRunescapeSmallFont());
		line.setForeground(color);
		line.setAlignmentX(Component.LEFT_ALIGNMENT);
		return line;
	}

	private static String skillDisplayName(String enumName)
	{
		if (enumName == null)
		{
			return "";
		}
		try
		{
			return Skill.valueOf(enumName.toUpperCase(Locale.ROOT)).getName();
		}
		catch (IllegalArgumentException e)
		{
			return enumName;
		}
	}

	private void addSection(JPanel panel, String title, List<RequirementStatus> statuses)
	{
		if (statuses.isEmpty())
		{
			return;
		}

		panel.add(sectionHeading(title));
		for (RequirementStatus status : statuses)
		{
			panel.add(coloredLine(requirementText(status.getRequirement()), requirementColor(status)));
		}
	}

	private JLabel mutedLabel(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private static String nameText(QuestEvaluation evaluation)
	{
		String questName = evaluation.getQuest().getName();
		if (isFinished(evaluation))
		{
			return "<html><strike>" + escape(questName) + "</strike></html>";
		}
		return questName;
	}

	private static String requirementText(QuestRequirement requirement)
	{
		String text = requirement.getName();
		if (requirement.getQuantity() > 1)
		{
			text = text + " x" + requirement.getQuantity();
		}
		return text;
	}

	private static Color requirementColor(RequirementStatus status)
	{
		if (!status.isGating())
		{
			return INFO_COLOR;
		}
		return status.isSatisfied() ? GOOD_COLOR : BAD_COLOR;
	}

	private static String countText(QuestEvaluation evaluation)
	{
		switch (evaluation.getReadiness())
		{
			case NO_DATA:
				return "no data";
			case NO_ITEMS_NEEDED:
				return "nothing needed";
			default:
				return evaluation.getAggregateSatisfied() + "/" + evaluation.getAggregateTotal();
		}
	}

	private static boolean isFinished(QuestEvaluation evaluation)
	{
		return evaluation.getQuestState() == QuestState.FINISHED;
	}

	static Color readinessColor(Readiness readiness)
	{
		switch (readiness)
		{
			case READY:
				return ColorScheme.PROGRESS_COMPLETE_COLOR;
			case PARTIAL:
				return ColorScheme.PROGRESS_INPROGRESS_COLOR;
			case BLOCKED:
				return ColorScheme.PROGRESS_ERROR_COLOR;
			case NO_ITEMS_NEEDED:
				return ColorScheme.LIGHT_GRAY_COLOR;
			case NO_DATA:
			default:
				return ColorScheme.MEDIUM_GRAY_COLOR;
		}
	}

	private static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

