package com.choicemanhelper;

import com.choicemanhelper.model.MinigameData;
import com.choicemanhelper.model.MinigameEvaluation;
import com.choicemanhelper.model.PlayerStats;
import com.choicemanhelper.model.Readiness;
import com.google.gson.Gson;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.QuestState;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;

/**
 * Focused tests for {@link MinigameEvaluator} using constructed data and a test-only
 * {@link UnlockService}. Mirrors {@link QuestEvaluatorTest}; the shared gating math lives in
 * {@link RequirementEvaluator} and is exercised in depth there via the quest tests, so these cover
 * the minigame-specific folding (no in-game state, no mid-content items).
 */
public class MinigameEvaluatorTest
{
	private static final Gson GSON = new Gson();

	private MinigameEvaluator evaluator;
	private PlayerStats stats = PlayerStats.EMPTY;
	private final Map<String, QuestState> prereqStates = new HashMap<>();

	@Before
	public void setUp()
	{
		Map<Integer, String> idToBase = new HashMap<>();
		idToBase.put(946, "Knife");
		idToBase.put(2347, "Hammer");
		idToBase.put(590, "Tinderbox");

		Set<String> unlocked = new HashSet<>();
		unlocked.add("Knife");

		UnlockService unlockService = UnlockService.createForTest(idToBase, unlocked);
		evaluator = new MinigameEvaluator(unlockService, null, null, null, null);
	}

	private MinigameEvaluation evaluate(String json)
	{
		MinigameData data = json == null ? null : GSON.fromJson(json, MinigameData.class);
		return evaluator.evaluate(data, false, stats, prereqStates::get);
	}

	private static PlayerStats statsWith(String skill, int level, int questPoints)
	{
		Map<String, Integer> levels = new HashMap<>();
		levels.put(skill, level);
		return new PlayerStats(levels, questPoints);
	}

	@Test
	public void nullDataReturnsNull()
	{
		Assert.assertNull(evaluate(null));
	}

	@Test
	public void noRequirementsIsNothingNeeded()
	{
		MinigameEvaluation eval = evaluate("{\"id\":\"x\",\"name\":\"Castle Wars\"}");
		Assert.assertEquals(Readiness.NO_ITEMS_NEEDED, eval.getReadiness());
		Assert.assertEquals(0, eval.getAggregateTotal());
		Assert.assertEquals("Castle Wars", eval.getName());
	}

	@Test
	public void wintertodtGatingItemsAndSkill()
	{
		// Knife unlocked, hammer + tinderbox locked, axe non-gating; 50 Firemaking met.
		stats = statsWith("FIREMAKING", 55, 0);
		MinigameEvaluation eval = evaluate(
			"{\"id\":\"wintertodt\",\"name\":\"Wintertodt\","
				+ "\"required\":[{\"name\":\"Knife\",\"itemIds\":[946]},"
				+ "{\"name\":\"Hammer\",\"itemIds\":[2347]},"
				+ "{\"name\":\"Tinderbox\",\"itemIds\":[590]},"
				+ "{\"name\":\"Axe\",\"itemIds\":[]}],"
				+ "\"skillRequirements\":[{\"skill\":\"FIREMAKING\",\"level\":50}]}");
		// 3 gating items (knife/hammer/tinderbox) + 1 skill = 4 blockers; knife + skill satisfied.
		Assert.assertEquals(Readiness.PARTIAL, eval.getReadiness());
		Assert.assertEquals(4, eval.getAggregateTotal());
		Assert.assertEquals(2, eval.getAggregateSatisfied());
		Assert.assertEquals(3, eval.getGatingTotal());
		Assert.assertEquals(1, eval.getGatingUnlocked());
	}

	@Test
	public void skillBelowRequirementBlocks()
	{
		stats = statsWith("FISHING", 20, 0);
		MinigameEvaluation eval = evaluate(
			"{\"id\":\"tempoross\",\"name\":\"Tempoross\","
				+ "\"skillRequirements\":[{\"skill\":\"FISHING\",\"level\":35}]}");
		Assert.assertEquals(Readiness.BLOCKED, eval.getReadiness());
		Assert.assertEquals(1, eval.getAggregateTotal());
		Assert.assertEquals(0, eval.getAggregateSatisfied());
	}

	@Test
	public void prerequisiteQuestGates()
	{
		String json = "{\"id\":\"gotr\",\"name\":\"Guardians of the Rift\","
			+ "\"questPrerequisites\":[\"TEMPLE_OF_THE_EYE\"]}";

		prereqStates.put("TEMPLE_OF_THE_EYE", QuestState.IN_PROGRESS);
		MinigameEvaluation blocked = evaluate(json);
		Assert.assertEquals(Readiness.BLOCKED, blocked.getReadiness());
		Assert.assertFalse(blocked.getPrerequisites().get(0).isFinished());

		prereqStates.put("TEMPLE_OF_THE_EYE", QuestState.FINISHED);
		MinigameEvaluation ready = evaluate(json);
		Assert.assertEquals(Readiness.READY, ready.getReadiness());
		Assert.assertTrue(ready.getPrerequisites().get(0).isFinished());
	}

	@Test
	public void recommendedIgnoredUnlessToggled()
	{
		String json = "{\"id\":\"x\",\"name\":\"Y\","
			+ "\"recommended\":[{\"name\":\"Hammer\",\"itemIds\":[2347]}]}";

		MinigameEvaluation off = evaluator.evaluate(GSON.fromJson(json, MinigameData.class), false, stats, prereqStates::get);
		Assert.assertEquals(Readiness.NO_ITEMS_NEEDED, off.getReadiness());

		MinigameEvaluation on = evaluator.evaluate(GSON.fromJson(json, MinigameData.class), true, stats, prereqStates::get);
		Assert.assertEquals(Readiness.BLOCKED, on.getReadiness());
		Assert.assertEquals(1, on.getGatingTotal());
	}
}

package com.choicemanhelper;

import com.choicemanhelper.model.PlayerStats;
import com.choicemanhelper.model.QuestEvaluation;
import com.choicemanhelper.model.QuestItemData;
import com.choicemanhelper.model.Readiness;
import com.choicemanhelper.model.RequirementStatus;
import com.google.gson.Gson;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;

/**
 * Focused tests for {@link QuestEvaluator} using plain constructed data and a test-only
 * {@link UnlockService}. No client mocking.
 */
public class QuestEvaluatorTest
{
	private static final Gson GSON = new Gson();
	private static final Quest ANY_QUEST = Quest.COOKS_ASSISTANT;

	private QuestEvaluator evaluator;

	/** Account stats used by the pure evaluator; individual tests override before evaluating. */
	private PlayerStats stats = PlayerStats.EMPTY;

	/** Cached prerequisite quest states, keyed by enum name; empty unless a test populates it. */
	private final Map<String, QuestState> prereqStates = new HashMap<>();

	@Before
	public void setUp()
	{
		// Gating item table: id -> Choice Man base name.
		Map<Integer, String> idToBase = new HashMap<>();
		idToBase.put(100, "Alpha");
		idToBase.put(101, "Beta");
		idToBase.put(102, "Gamma");
		idToBase.put(200, "Runes");
		idToBase.put(201, "Coins");

		// Unlocked bases: Alpha and Runes only. Id 999 is untracked (non-gating).
		Set<String> unlocked = new HashSet<>();
		unlocked.add("Alpha");
		unlocked.add("Runes");

		UnlockService unlockService = UnlockService.createForTest(idToBase, unlocked);
		evaluator = new QuestEvaluator(unlockService, null, null, null, null);
	}

	private QuestEvaluation evaluate(String json)
	{
		return evaluate(json, false);
	}

	private QuestEvaluation evaluate(String json, boolean includeRecommended)
	{
		QuestItemData data = json == null ? null : GSON.fromJson(json, QuestItemData.class);
		return evaluator.evaluate(ANY_QUEST, null, data, includeRecommended, stats, prereqStates::get);
	}

	private static PlayerStats statsWith(String skill, int level, int questPoints)
	{
		Map<String, Integer> levels = new HashMap<>();
		levels.put(skill, level);
		return new PlayerStats(levels, questPoints);
	}

	@Test
	public void allRequiredUnlockedIsReady()
	{
		QuestEvaluation eval = evaluate("{\"required\":[{\"name\":\"Alpha\",\"itemIds\":[100]}]}");
		Assert.assertEquals(Readiness.READY, eval.getReadiness());
		Assert.assertEquals(1, eval.getGatingTotal());
		Assert.assertEquals(1, eval.getGatingUnlocked());
		Assert.assertTrue(eval.getRequired().get(0).isSatisfied());
		Assert.assertTrue(eval.getRequired().get(0).isGating());
	}

	@Test
	public void someRequiredUnlockedIsPartial()
	{
		QuestEvaluation eval = evaluate(
			"{\"required\":[{\"name\":\"Alpha\",\"itemIds\":[100]},{\"name\":\"Beta\",\"itemIds\":[101]}]}");
		Assert.assertEquals(Readiness.PARTIAL, eval.getReadiness());
		Assert.assertEquals(2, eval.getGatingTotal());
		Assert.assertEquals(1, eval.getGatingUnlocked());
	}

	@Test
	public void noneUnlockedIsBlocked()
	{
		QuestEvaluation eval = evaluate(
			"{\"required\":[{\"name\":\"Beta\",\"itemIds\":[101]},{\"name\":\"Gamma\",\"itemIds\":[102]}]}");
		Assert.assertEquals(Readiness.BLOCKED, eval.getReadiness());
		Assert.assertEquals(2, eval.getGatingTotal());
		Assert.assertEquals(0, eval.getGatingUnlocked());
	}

	@Test
	public void alternativeGroupsSatisfiedWhenAnyGroupSatisfied()
	{
		QuestEvaluation eval = evaluate(
			"{\"required\":[{\"name\":\"Runes or coins\",\"itemIds\":[200,201],"
				+ "\"alternativeGroups\":[{\"name\":\"Runes\",\"itemIds\":[200]},"
				+ "{\"name\":\"Coins\",\"itemIds\":[201]}]}]}");
		Assert.assertEquals(Readiness.READY, eval.getReadiness());
		Assert.assertTrue(eval.getRequired().get(0).isSatisfied());
		Assert.assertTrue(eval.getRequired().get(0).isGating());
	}

	@Test
	public void alternativeGroupsBlockedWhenNoGroupSatisfied()
	{
		QuestEvaluation eval = evaluate(
			"{\"required\":[{\"name\":\"Beta or coins\","
				+ "\"alternativeGroups\":[{\"name\":\"Beta\",\"itemIds\":[101]},"
				+ "{\"name\":\"Coins\",\"itemIds\":[201]}]}]}");
		Assert.assertEquals(Readiness.BLOCKED, eval.getReadiness());
		Assert.assertFalse(eval.getRequired().get(0).isSatisfied());
	}

	@Test
	public void nonGatingItemNeverGates()
	{
		// Id 999 is not in the table, so it is freely usable and does not gate.
		QuestEvaluation eval = evaluate("{\"required\":[{\"name\":\"Free item\",\"itemIds\":[999]}]}");
		Assert.assertEquals(Readiness.NO_ITEMS_NEEDED, eval.getReadiness());
		Assert.assertEquals(0, eval.getGatingTotal());
		Assert.assertTrue(eval.getRequired().get(0).isSatisfied());
		Assert.assertFalse(eval.getRequired().get(0).isGating());
	}

	@Test
	public void gatingRequirementNotSatisfiedByNonGatingAlternate()
	{
		// Druidic Ritual case: a locked gating id (raw meat, 101) plus a non-gating alternate
		// (the untradeable enchanted form, 999). The free id must NOT satisfy the requirement,
		// because the real unlockable item is still locked.
		QuestEvaluation eval = evaluate("{\"required\":[{\"name\":\"Raw meat or enchanted\",\"itemIds\":[101,999]}]}");
		Assert.assertEquals(Readiness.BLOCKED, eval.getReadiness());
		Assert.assertEquals(1, eval.getGatingTotal());
		Assert.assertEquals(0, eval.getGatingUnlocked());
		Assert.assertTrue(eval.getRequired().get(0).isGating());
		Assert.assertFalse(eval.getRequired().get(0).isSatisfied());
	}

	@Test
	public void gatingRequirementSatisfiedWhenAGatingIdIsUnlocked()
	{
		// Unlocked gating id (Alpha, 100) plus a non-gating alternate: satisfied via the unlock.
		QuestEvaluation eval = evaluate("{\"required\":[{\"name\":\"Alpha or free\",\"itemIds\":[100,999]}]}");
		Assert.assertEquals(Readiness.READY, eval.getReadiness());
		Assert.assertTrue(eval.getRequired().get(0).isSatisfied());
		Assert.assertTrue(eval.getRequired().get(0).isGating());
	}

	@Test
