	@Test
	public void questPointsMetAndUnmet()
	{
		String json = "{\"questPoints\":32}";

		stats = statsWith("AGILITY", 1, 40);
		QuestEvaluation met = evaluate(json);
		Assert.assertEquals(Readiness.READY, met.getReadiness());
		Assert.assertEquals(1, met.getAggregateTotal());
		Assert.assertEquals(32, met.getQuestPointsRequired());
		Assert.assertEquals(40, met.getQuestPointsCurrent());

		stats = statsWith("AGILITY", 1, 10);
		QuestEvaluation unmet = evaluate(json);
		Assert.assertEquals(Readiness.BLOCKED, unmet.getReadiness());
		Assert.assertEquals(0, unmet.getAggregateSatisfied());
	}

	@Test
	public void prerequisiteFinishedAndUnfinished()
	{
		String json = "{\"questPrerequisites\":[\"COOKS_ASSISTANT\"]}";

		prereqStates.put("COOKS_ASSISTANT", QuestState.FINISHED);
		QuestEvaluation done = evaluate(json);
		Assert.assertEquals(Readiness.READY, done.getReadiness());
		Assert.assertEquals(1, done.getAggregateTotal());
		Assert.assertTrue(done.getPrerequisites().get(0).isFinished());
		Assert.assertEquals("Cook's Assistant", done.getPrerequisites().get(0).getDisplayName());

		prereqStates.put("COOKS_ASSISTANT", QuestState.IN_PROGRESS);
		QuestEvaluation notDone = evaluate(json);
		Assert.assertEquals(Readiness.BLOCKED, notDone.getReadiness());
		Assert.assertFalse(notDone.getPrerequisites().get(0).isFinished());
	}

	@Test
	public void allDimensionsMetIsReady()
	{
		stats = statsWith("AGILITY", 30, 50);
