	}

	@Test
	public void mixedDimensionsProducePartial()
	{
		// Item unlocked, skill met, but prerequisite unfinished -> 2 of 3 satisfied.
		stats = statsWith("AGILITY", 30, 0);
		prereqStates.put("COOKS_ASSISTANT", QuestState.NOT_STARTED);
		QuestEvaluation eval = evaluate(
			"{\"required\":[{\"name\":\"Alpha\",\"itemIds\":[100]}],"
				+ "\"skillRequirements\":[{\"skill\":\"AGILITY\",\"level\":20}],"
				+ "\"questPrerequisites\":[\"COOKS_ASSISTANT\"]}");
		Assert.assertEquals(Readiness.PARTIAL, eval.getReadiness());
		Assert.assertEquals(3, eval.getAggregateTotal());
		Assert.assertEquals(2, eval.getAggregateSatisfied());
	}
